                    <div class="info-form">
                        <div class="form-group">
                            <label for="char-name">姓名</label>
                            <input type="text" id="char-name" placeholder="若不填则默认为{{user}}">
                        </div>
                        <div class="form-group">
                            <label for="char-age">年龄</label>
                            <input type="number" id="char-age" placeholder="转生后的年龄">
                        </div>
                        <div class="form-group">
                            <label for="char-gender">性别</label>
                            <input type="text" id="char-gender" placeholder="例如: 男性/女性/其他">
                        </div>
                        <div class="form-group full-width">
                            <label for="char-appearance">外貌特征</label>
                            <textarea id="char-appearance" placeholder="请描述角色的外貌特征、穿着风格等..."></textarea>
                        </div>
                    </div>
                </div>

                <!-- 第二步：属性分配 -->
                <div class="panel">
                    <h2 class="panel-title"><i class="fas fa-dice-d20"></i> 第二步：属性分配</h2>
                    <div class="stats-container">
                        <!-- Strength -->
                        <div class="stat-card">
                            <div class="stat-header">
                                <div class="stat-icon">⚔️</div>
                                <div class="stat-name">力量(STR)</div>
                                <div class="stat-en-name">Strength</div>
                                <div class="stat-desc">衡量肌肉力量、负重能力与爆发力</div>
                            </div>
                            <div class="stat-controls">
                                <button class="stat-btn" id="str-dec">-</button>
                                <div class="stat-values">
                                    <div class="stat-value" id="str-value">8</div>
                                    <div class="stat-modifier" id="str-mod">-1</div>
                                </div>
                                <button class="stat-btn" id="str-inc">+</button>
                            </div>
                            <div class="stat-cost">花费点数: <span id="str-cost">0</span></div>
                        </div>

                        <!-- Dexterity -->
                        <div class="stat-card">
                            <div class="stat-header">
                                <div class="stat-icon">🏹</div>
                                <div class="stat-name">敏捷(DEX)</div>
                                <div class="stat-en-name">Dexterity</div>
                                <div class="stat-desc">衡量反应速度、身体协调性与灵活性</div>
                            </div>
                            <div class="stat-controls">
                                <button class="stat-btn" id="dex-dec">-</button>
                                <div class="stat-values">
                                    <div class="stat-value" id="dex-value">8</div>
                                    <div class="stat-modifier" id="dex-mod">-1</div>
                                </div>
                                <button class="stat-btn" id="dex-inc">+</button>
                            </div>
                            <div class="stat-cost">花费点数: <span id="dex-cost">0</span></div>
                        </div>

                        <!-- Constitution -->
                        <div class="stat-card">
                            <div class="stat-header">
                                <div class="stat-icon">❤️</div>
                                <div class="stat-name">体质(CON)</div>
                                <div class="stat-en-name">Constitution</div>
                                <div class="stat-desc">衡量健康状况、抵抗力与耐力</div>
