        .skill-attr {
            background: rgba(90, 58, 140, 0.7);
            color: #d4af37;
            padding: 3px 10px;
            border-radius: 15px;
            font-size: 0.9rem;
        }

        .skill-desc {
            font-size: 0.9rem;
            color: #d0c0e0;
            line-height: 1.5;
        }

        .skill-checkbox {
            display: none;
        }

        .selected-count {
            text-align: center;
            margin: 20px 0;
            font-size: 1.1rem;
            color: #d4af37;
        }

        /* 熟练系统说明 */
        .proficiency-section {
            margin-top: 30px;
        }

        .proficiency-box {
            background: rgba(45, 35, 65, 0.8);
            border-radius: 10px;
            padding: 20px;
            border: 1px solid #6a4a9c;
            margin-top: 15px;
        }

        .proficiency-box h3 {
            color: #d4af37;
            margin-bottom: 15px;
            font-size: 1.3rem;
        }

        .proficiency-box p {
            margin-bottom: 15px;
            line-height: 1.6;
            color: #d0c0e0;
        }

        .proficiency-box ul {
            padding-left: 20px;
            margin-bottom: 15px;
        }

        .proficiency-box li {
            margin-bottom: 10px;
            line-height: 1.5;
            color: #d0c0e0;
        }

        /* 提交按钮 */
        .submit-section {
            margin-top: 30px;
            text-align: center;
        }

        .submit-btn {
            background: linear-gradient(145deg, #5a3a8c, #4a2c6d);
            color: #d4af37;
            border: 2px solid #d4af37;
            border-radius: 30px;
            padding: 15px 50px;
            font-size: 1.3rem;
            font-weight: bold;
            cursor: pointer;
            transition: all 0.4s;
            letter-spacing: 1px;
            position: relative;
            overflow: hidden;
            z-index: 1;
        }

        .submit-btn:hover {
            background: linear-gradient(145deg, #d4af37, #c5a23d);
            color: #1a0a2e;
            box-shadow: 0 0 25px rgba(212, 175, 55, 0.5);
            transform: translateY(-3px);
        }

        .submit-btn:disabled {
            opacity: 0.6;
            cursor: not-allowed;
            background: linear-gradient(145deg, #4a2c6d, #351d59);
            color: #888;
            border-color: #666;
        }

        /* 确认面板 */
        .confirmation-panel {
            background: rgba(45, 35, 65, 0.9);
            border-radius: 10px;
            padding: 25px;
            margin-top: 25px;
            border: 1px solid #6a4a9c;
        }

        .confirmation-title {
            font-size: 1.4rem;
            color: #d4af37;
            margin-bottom: 20px;
            text-align: center;
        }

        .confirmation-group {
            margin-bottom: 15px;
            padding-bottom: 15px;
            border-bottom: 1px solid rgba(106, 74, 156, 0.5);
        }

        .confirmation-label {
            color: #d4af37;
            font-weight: bold;
            margin-bottom: 8px;
            font-size: 1.1rem;
        }

        .confirmation-value {
            color: #f5f5f5;
            line-height: 1.6;
        }

        .attributes-grid {
            display: grid;
            grid-template-columns: repeat(3, 1fr);
            gap: 15px;
            margin-top: 10px;
        }

        .attribute-confirm {
            background: rgba(26, 16, 46, 0.7);
            padding: 12px;
            border-radius: 8px;
            text-align: center;
        }

        .attribute-name-confirm {
            color: #d4af37;
            font-weight: bold;
            margin-bottom: 5px;
        }

        .attribute-value-confirm {
            font-size: 1.4rem;
            font-weight: bold;
        }

        .skills-list {
            display: grid;
            grid-template-columns: repeat(2, 1fr);
            gap: 10px;
            margin-top: 10px;
        }

        .skill-confirm {
            background: rgba(26, 16, 46, 0.7);
            padding: 10px;
            border-radius: 6px;
            font-size: 0.95rem;
        }

        /* 感谢页面 */
        #credits-screen {
            position: fixed;
            top: 0;
            left: 0;
            width: 100vw;
            height: 100vh;
            background: radial-gradient(ellipse at center, rgba(29, 16, 54, 0.97) 0%, rgba(53, 29, 89, 0.97) 100%);
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            z-index: 9999;
            pointer-events: none;
            opacity: 0;
            transition: opacity 0.8s cubic-bezier(.33,1.38,.9,.98);
        }

        #credits-screen p {
            font-family: 'Cinzel', serif;
            font-size: 3.5rem;
            color: #d4af37;
            text-shadow: 0 0 15px #000, 0 0 40px #c5a23d;
            letter-spacing: 5px;
            text-align: center;
            margin: 0 0 50px 0;
            animation: glow 2s infinite alternate;
        }

        #credits-screen .subtext {
            font-size: 1.5rem;
            color: #c0a9d6;
            max-width: 600px;
            text-align: center;
            margin-top: 20px;
        }

        @keyframes glow {
            from { text-shadow: 0 0 15px #000, 0 0 40px #c5a23d; }
            to { text-shadow: 0 0 20px #000, 0 0 50px #d4af37, 0 0 60px #d4af37; }
        }

        .validation-message {
            text-align: center;
            color: #ff9e9e;
            font-size: 1.1rem;
            font-weight: bold;
            margin-top: 15px;
            height: 1.5em;
            opacity: 0;
            will-change: opacity,transform;
            text-shadow: 0 1px 2px rgba(0,0,0,0.5);
        }

        @media (max-width: 768px) {
            .stats-container {
                grid-template-columns: repeat(2, 1fr);
            }

            .points-info {
                flex-direction: column;
                gap: 15px;
            }

            h1 {
                font-size: 2.2rem;
            }

            .attributes-grid {
                grid-template-columns: repeat(2, 1fr);
            }

            .skills-list {
                grid-template-columns: 1fr;
            }
        }
    </style>
</head>
<body>
    <div class="container">
        <header>
            <div class="title-container">
                <h1>九狱转生定制器™</h1>
                <p class="subtitle">由九狱集团倾情开发，专供转生者们塑造最令他们满意的异世界角色</p>
            </div>
        </header>

        <div class="main-content">
            <div class="left-panel">
                <!-- 第一步：个人信息 -->
                <div class="panel">
                    <h2 class="panel-title"><i class="fas fa-user"></i> 第一步：个人信息</h2>
                    <div class="info-form">
                        <div class="form-group">
                            <label for="char-name">姓名</label>
                            <input type="text" id="char-name" placeholder="若不填则默认为{{user}}">
                        </div>
                        <div class="form-group">
                            <label for="char-age">年龄</label>
                            <input type="number" id="char-age" placeholder="转生后的年龄">
                        </div>
                        <div class="form-group">
                            <label for="char-gender">性别</label>
                            <input type="text" id="char-gender" placeholder="例如: 男性/女性/其他">
                        </div>
                        <div class="form-group full-width">
                            <label for="char-appearance">外貌特征</label>
                            <textarea id="char-appearance" placeholder="请描述角色的外貌特征、穿着风格等..."></textarea>
                        </div>
                    </div>
                </div>

                <!-- 第二步：属性分配 -->
                <div class="panel">
                    <h2 class="panel-title"><i class="fas fa-dice-d20"></i> 第二步：属性分配</h2>
                    <div class="stats-container">
                        <!-- Strength -->
                        <div class="stat-card">
                            <div class="stat-header">
                                <div class="stat-icon">⚔️</div>
                                <div class="stat-name">力量(STR)</div>
                                <div class="stat-en-name">Strength</div>
                                <div class="stat-desc">衡量肌肉力量、负重能力与爆发力</div>
                            </div>
                            <div class="stat-controls">
                                <button class="stat-btn" id="str-dec">-</button>
                                <div class="stat-values">
                                    <div class="stat-value" id="str-value">8</div>
                                    <div class="stat-modifier" id="str-mod">-1</div>
                                </div>
                                <button class="stat-btn" id="str-inc">+</button>
                            </div>
                            <div class="stat-cost">花费点数: <span id="str-cost">0</span></div>
                        </div>

                        <!-- Dexterity -->
                        <div class="stat-card">
                            <div class="stat-header">
                                <div class="stat-icon">🏹</div>
                                <div class="stat-name">敏捷(DEX)</div>
                                <div class="stat-en-name">Dexterity</div>
                                <div class="stat-desc">衡量反应速度、身体协调性与灵活性</div>
                            </div>
                            <div class="stat-controls">
                                <button class="stat-btn" id="dex-dec">-</button>
                                <div class="stat-values">
                                    <div class="stat-value" id="dex-value">8</div>
                                    <div class="stat-modifier" id="dex-mod">-1</div>
                                </div>
                                <button class="stat-btn" id="dex-inc">+</button>
                            </div>
                            <div class="stat-cost">花费点数: <span id="dex-cost">0</span></div>
                        </div>

                        <!-- Constitution -->
                        <div class="stat-card">
                            <div class="stat-header">
                                <div class="stat-icon">❤️</div>
                                <div class="stat-name">体质(CON)</div>
                                <div class="stat-en-name">Constitution</div>
                                <div class="stat-desc">衡量健康状况、抵抗力与耐力</div>
                            </div>
                            <div class="stat-controls">
                                <button class="stat-btn" id="con-dec">-</button>
                                <div class="stat-values">
                                    <div class="stat-value" id="con-value">8</div>
                                    <div class="stat-modifier" id="con-mod">-1</div>
                                </div>
                                <button class="stat-btn" id="con-inc">+</button>
                            </div>
                            <div class="stat-cost">花费点数: <span id="con-cost">0</span></div>
                        </div>

                        <!-- Intelligence -->
                        <div class="stat-card">
                            <div class="stat-header">
                                <div class="stat-icon">📚</div>
                                <div class="stat-name">智力(INT)</div>
                                <div class="stat-en-name">Intelligence</div>
                                <div class="stat-desc">衡量逻辑推理、知识积累与学习能力</div>
                            </div>
                            <div class="stat-controls">
                                <button class="stat-btn" id="int-dec">-</button>
                                <div class="stat-values">
                                    <div class="stat-value" id="int-value">8</div>
                                    <div class="stat-modifier" id="int-mod">-1</div>
                                </div>
                                <button class="stat-btn" id="int-inc">+</button>
                            </div>
                            <div class="stat-cost">花费点数: <span id="int-cost">0</span></div>
                        </div>

                        <!-- Wisdom -->
                        <div class="stat-card">
                            <div class="stat-header">
                                <div class="stat-icon">🔮</div>
                                <div class="stat-name">感知(WIS)</div>
                                <div class="stat-en-name">Wisdom</div>
                                <div class="stat-desc">衡量环境敏锐度、自我控制力与直觉</div>
                            </div>
                            <div class="stat-controls">
                                <button class="stat-btn" id="wis-dec">-</button>
                                <div class="stat-values">
                                    <div class="stat-value" id="wis-value">8</div>
                                    <div class="stat-modifier" id="wis-mod">-1</div>
                                </div>
                                <button class="stat-btn" id="wis-inc">+</button>
                            </div>
                            <div class="stat-cost">花费点数: <span id="wis-cost">0</span></div>
                        </div>

                        <!-- Charisma -->
                        <div class="stat-card">
                            <div class="stat-header">
                                <div class="stat-icon">🎭</div>
                                <div class="stat-name">魅力(CHA)</div>
                                <div class="stat-en-name">Charisma</div>
                                <div class="stat-desc">衡量气场、影响他人的能力与内在自信</div>
                            </div>
                            <div class="stat-controls">
                                <button class="stat-btn" id="cha-dec">-</button>
                                <div class="stat-values">
                                    <div class="stat-value" id="cha-value">8</div>
                                    <div class="stat-modifier" id="cha-mod">-1</div>
                                </div>
                                <button class="stat-btn" id="cha-inc">+</button>
                            </div>
                            <div class="stat-cost">花费点数: <span id="cha-cost">0</span></div>
                        </div>
                    </div>

                    <div class="point-summary">
                        <div class="summary-title">点数摘要</div>
                        <div class="points-info">
                            <div class="point-box remaining-points">
                                <div class="point-label">剩余点数</div>
                                <div class="point-value" id="remaining-points">27</div>
                            </div>
                            <div class="point-box used-points">
                                <div class="point-label">已用点数</div>
                                <div class="point-value" id="used-points">0</div>
                            </div>
                        </div>
                        <button class="reset-btn" id="reset-btn">重置所有属性</button>
                    </div>

                    <div class="radar-container">
                        <canvas id="radar-chart"></canvas>
                    </div>
                </div>
            </div>

            <div class="right-panel">
                <!-- 第三步：熟练选择 -->
                <div class="panel">
                    <h2 class="panel-title"><i class="fas fa-tasks"></i> 第三步：熟练选择</h2>
                    <div class="selected-count">
                        已选择: <span id="selected-count">0</span> / 4 个技能
                    </div>

                    <div class="skills-container">
                        <!-- 技能列表 -->
                        <div class="skill-card" data-skill="特技">
                            <div class="skill-header">
                                <div>
                                    <div class="skill-name">特技</div>
                                    <div class="skill-en-name">Acrobatics</div>
                                </div>
                                <div class="skill-attr">敏捷</div>
                            </div>
                            <div class="skill-desc">翻滚、闪避、跳跃、杂技动作或在复杂环境中保持平衡</div>
                        </div>

                        <div class="skill-card" data-skill="交际">
                            <div class="skill-header">
                                <div>
                                    <div class="skill-name">交际</div>
                                    <div class="skill-en-name">Charm</div>
                                </div>
                                <div class="skill-attr">魅力</div>
                            </div>
                            <div class="skill-desc">说服、欺瞒、煽动、引导谈话或引人注意</div>
                        </div>

                        <div class="skill-card" data-skill="洞察">
                            <div class="skill-header">
                                <div>
                                    <div class="skill-name">洞察</div>
                                    <div class="skill-en-name">Insight</div>
                                </div>
                                <div class="skill-attr">感知</div>
                            </div>
                            <div class="skill-desc">理解他人情绪、判断真假、识破意图</div>
                        </div>

                        <div class="skill-card" data-skill="察觉">
                            <div class="skill-header">
                                <div>
                                    <div class="skill-name">察觉</div>
                                    <div class="skill-en-name">Perception</div>
                                </div>
                                <div class="skill-attr">感知</div>
                            </div>
                            <div class="skill-desc">注意细节、发现埋伏、感知周围环境变化</div>
                        </div>

                        <div class="skill-card" data-skill="魔导学">
                            <div class="skill-header">
                                <div>
                                    <div class="skill-name">魔导学</div>
                                    <div class="skill-en-name">Magitek</div>
                                </div>
                                <div class="skill-attr">智力</div>
                            </div>
                            <div class="skill-desc">辨识魔法装置、魔导反应、解析古代科技与术式</div>
                        </div>

                        <div class="skill-card" data-skill="博识">
                            <div class="skill-header">
                                <div>
                                    <div class="skill-name">博识</div>
                                    <div class="skill-en-name">Lore</div>
                                </div>
                                <div class="skill-attr">智力</div>
                            </div>
                            <div class="skill-desc">掌握历史、神话、贵族传承、文化传统等知识</div>
                        </div>

                        <div class="skill-card" data-skill="调查">
                            <div class="skill-header">
                                <div>
                                    <div class="skill-name">调查</div>
                                    <div class="skill-en-name">Investigation</div>
                                </div>
                                <div class="skill-attr">智力</div>
                            </div>
                            <div class="skill-desc">推理、搜查现场、阅读复杂文档与破译谜题</div>
                        </div>

                        <div class="skill-card" data-skill="运动">
                            <div class="skill-header">
                                <div>
                                    <div class="skill-name">运动</div>
                                    <div class="skill-en-name">Athletics</div>
                                </div>
                                <div class="skill-attr">力量</div>
                            </div>
                            <div class="skill-desc">攀爬、跳跃、强行打开、拖拉、游泳等体能行为</div>
                        </div>

                        <div class="skill-card" data-skill="隐匿">
                            <div class="skill-header">
                                <div>
                                    <div class="skill-name">隐匿</div>
                                    <div class="skill-en-name">Stealth</div>
                                </div>
                                <div class="skill-attr">敏捷</div>
                            </div>
                            <div class="skill-desc">悄无声息地移动、躲藏、逃避监视或刺探</div>
                        </div>

                        <div class="skill-card" data-skill="求生">
                            <div class="skill-header">
                                <div>
                                    <div class="skill-name">求生</div>
                                    <div class="skill-en-name">Survival</div>
                                </div>
                                <div class="skill-attr">感知</div>
                            </div>
                            <div class="skill-desc">追踪野兽、识别地貌、避开自然灾害或野外求生</div>
                        </div>

                        <div class="skill-card" data-skill="医药">
                            <div class="skill-header">
                                <div>
                                    <div class="skill-name">医药</div>
                                    <div class="skill-en-name">Medicine</div>
                                </div>
                                <div class="skill-attr">感知</div>
                            </div>
                            <div class="skill-desc">施行急救、判断伤势、识别中毒或诊断病症</div>
                        </div>

                        <div class="skill-card" data-skill="灵感">
                            <div class="skill-header">
                                <div>
                                    <div class="skill-name">灵感</div>
                                    <div class="skill-en-name">Inspiration</div>
                                </div>
                                <div class="skill-attr">智力</div>
                            </div>
                            <div class="skill-desc">当遇到剧情僵局或困境时，请求 AI 提供创意、线索或外部灵感（每日限用）</div>
                        </div>
                    </div>
                </div>

                <!-- 熟练系统说明 -->
                <div class="proficiency-section">
                    <h3 class="section-title"><i class="fas fa-graduation-cap"></i> 熟练系统说明</h3>

                    <div class="proficiency-box">
                        <h3>属性数值含义</h3>
                        <div class="table-container">
                            <table>
                                <thead>
                                    <tr>
                                        <th>属性范围</th>
                                        <th>描述</th>
                                    </tr>
                                </thead>
                                <tbody>
                                    <tr>
                                        <td>1</td>
                                        <td>生理或精神功能严重损坏，濒临无法行动</td>
                                    </tr>
                                    <tr>
                                        <td>2-9</td>
                                        <td>低于常人水准，体弱或缺乏训练</td>
                                    </tr>
                                    <tr>
                                        <td>10-11</td>
                                        <td>人类平均水平，既不突出也不落后</td>
                                    </tr>
                                    <tr>
                                        <td>12-19</td>
                                        <td>远高于常人，表现出色，有专业水准或天赋</td>
                                    </tr>
                                    <tr>
                                        <td>20</td>
                                        <td>人类极限，几乎无法再进一步</td>
                                    </tr>
                                    <tr>
                                        <td>21-29</td>
                                        <td>超凡脱俗，通常只在强大生物或神祇身上出现</td>
                                    </tr>
                                    <tr>
                                        <td>30</td>
                                        <td>理论上的绝对极限，已无法用常识衡量</td>
                                    </tr>
                                </tbody>
                            </table>
                        </div>

                        <h3>属性调整值</h3>
                        <div class="table-container" style="margin-top: 15px;">
                            <table>
                                <thead>
                                    <tr>
                                        <th>属性值范围</th>
                                        <th>调整值</th>
                                    </tr>
                                </thead>
                                <tbody>
                                    <tr>
                                        <td>1</td>
                                        <td>-5</td>
                                    </tr>
                                    <tr>
                                        <td>2-3</td>
                                        <td>-4</td>
                                    </tr>
                                    <tr>
                                        <td>4-5</td>
                                        <td>-3</td>
                                    </tr>
                                    <tr>
                                        <td>6-7</td>
                                        <td>-2</td>
                                    </tr>
                                    <tr>
                                        <td>8-9</td>
                                        <td>-1</td>
                                    </tr>
                                    <tr>
                                        <td>10-11</td>
                                        <td>0</td>
                                    </tr>
                                    <tr>
                                        <td>12-13</td>
                                        <td>+1</td>
                                    </tr>
                                    <tr>
                                        <td>14-15</td>
                                        <td>+2</td>
                                    </tr>
                                    <tr>
                                        <td>16-17</td>
                                        <td>+3</td>
                                    </tr>
                                    <tr>
                                        <td>18-19</td>
                                        <td>+4</td>
                                    </tr>
                                    <tr>
                                        <td>20-21</td>
                                        <td>+5</td>
                                    </tr>
                                    <tr>
