                    </div>

                    <div class="proficiency-box">
                        <h3>熟练加值</h3>
                        <p>熟练加值会随着角色等级或怪物挑战等级提升，代表训练积累带来的成效。</p>

                        <div class="table-container" style="margin: 15px 0;">
                            <table>
                                <thead>
                                    <tr>
                                        <th>等级范围</th>
                                        <th>熟练加值</th>
                                    </tr>
                                </thead>
                                <tbody>
                                    <tr>
                                        <td>1-4级</td>
                                        <td>+2</td>
                                    </tr>
                                    <tr>
                                        <td>5-8级</td>
                                        <td>+3</td>
                                    </tr>
                                    <tr>
                                        <td>9-12级</td>
                                        <td>+4</td>
                                    </tr>
                                    <tr>
                                        <td>13-16级</td>
                                        <td>+5</td>
                                    </tr>
                                    <tr>
                                        <td>17-20级</td>
                                        <td>+6</td>
                                    </tr>
                                    <tr>
                                        <td>21-24级</td>
                                        <td>+7</td>
                                    </tr>
                                    <tr>
                                        <td>25-28级</td>
                                        <td>+8</td>
                                    </tr>
                                    <tr>
                                        <td>29-30级</td>
                                        <td>+9</td>
                                    </tr>
                                </tbody>
                            </table>
                        </div>

                        <p><strong>叠加规则:</strong> 熟练加值不能重复叠加使用；在需要时，可以被翻倍（如专精）或减半，但仅计算一次加值。</p>
                        <p><strong>适用范围:</strong></p>
                        <ul>
                            <li>技能检定（如察觉、运动、魔导学）</li>
                            <li>攻击检定（如熟练于某种武器）</li>
                            <li>法术豁免 DC 与法术攻击加值的计算</li>
                        </ul>
                    </div>

                    <div class="proficiency-box">
                        <h3>技能属性组合调整</h3>
                        <p>默认每项技能关联固定属性，但 AI 主持可根据行为叙述允许技能搭配其他属性</p>

                        <p><strong>例子:</strong></p>
                        <ul>
                            <li><strong>行为:</strong> 用蛮力威吓守卫<br>
                                <strong>检定:</strong> 力量（交际）
                            </li>
                            <li><strong>行为:</strong> 用机关学分析古代神庙构造陷阱<br>
                                <strong>检定:</strong> 智力（求生）
                            </li>
                        </ul>
                    </div>
                </div>

                <!-- 第四步：信息确认 -->
                <div class="panel">
                    <h2 class="panel-title"><i class="fas fa-check-circle"></i> 第四步：信息确认</h2>

                    <div class="confirmation-panel">
                        <div class="confirmation-group">
                            <div class="confirmation-label">基本信息</div>
                            <div class="confirmation-value" id="confirm-name">姓名：未设置</div>
                            <div class="confirmation-value" id="confirm-age">年龄：未设置</div>
                            <div class="confirmation-value" id="confirm-gender">性别：未设置</div>
                            <div class="confirmation-value" id="confirm-appearance">外貌：未设置</div>
                        </div>

                        <div class="confirmation-group">
                            <div class="confirmation-label">属性分配</div>
                            <div class="attributes-grid">
                                <div class="attribute-confirm">
                                    <div class="attribute-name-confirm">力量</div>
                                    <div class="attribute-value-confirm" id="confirm-str">8</div>
                                </div>
                                <div class="attribute-confirm">
                                    <div class="attribute-name-confirm">敏捷</div>
                                    <div class="attribute-value-confirm" id="confirm-dex">8</div>
                                </div>
                                <div class="attribute-confirm">
                                    <div class="attribute-name-confirm">体质</div>
                                    <div class="attribute-value-confirm" id="confirm-con">8</div>
                                </div>
                                <div class="attribute-confirm">
                                    <div class="attribute-name-confirm">智力</div>
                                    <div class="attribute-value-confirm" id="confirm-int">8</div>
                                </div>
                                <div class="attribute-confirm">
                                    <div class="attribute-name-confirm">感知</div>
                                    <div class="attribute-value-confirm" id="confirm-wis">8</div>
                                </div>
                                <div class="attribute-confirm">
                                    <div class="attribute-name-confirm">魅力</div>
                                    <div class="attribute-value-confirm" id="confirm-cha">8</div>
                                </div>
                            </div>
                        </div>

                        <div class="confirmation-group">
                            <div class="confirmation-label">已选技能</div>
                            <div class="confirmation-value" id="confirm-skills">无</div>
                            <div class="skills-list" id="skills-list">
                                <!-- 动态生成的技能列表 -->
                            </div>
                        </div>

                        <div class="confirmation-group">
                            <div class="confirmation-label">点数使用</div>
                            <div class="confirmation-value">已用点数：<span id="confirm-used">0</span>/27</div>
                        </div>
                    </div>
                </div>

                <!-- 提交按钮 -->
                <div class="submit-section">
                    <button id="submit-btn" class="submit-btn" disabled>提交信息，开始冒险</button>
                    <div id="validation-message" class="validation-message"></div>
                </div>
            </div>
        </div>
    </div>

    <!-- 感谢页面 -->
    <div id="credits-screen">
        <p>感谢您选择<br>九狱转生定制器™！</p>
        <div class="subtext">角色信息已成功提交，即将开始您的异世界冒险之旅...</div>
    </div>

    <script>
        // 初始属性值
        const baseStat = 8;
        const totalPoints = 27;
        const maxSkills = 4;

        // 属性状态
        const stats = {
            str: { value: 8, cost: 0 },
            dex: { value: 8, cost: 0 },
            con: { value: 8, cost: 0 },
            int: { value: 8, cost: 0 },
            wis: { value: 8, cost: 0 },
            cha: { value: 8, cost: 0 }
        };

        // 选择的技能
        let selectedSkills = [];

        // 初始化雷达图
        const radarCtx = document.getElementById('radar-chart').getContext('2d');
        let radarChart = new Chart(radarCtx, {
            type: 'radar',
            data: {
                labels: ['力量', '敏捷', '体质', '智力', '感知', '魅力'],
                datasets: [{
                    label: '属性值',
                    data: [8, 8, 8, 8, 8, 8],
                    fill: true,
                    backgroundColor: 'rgba(90, 58, 140, 0.3)',
                    borderColor: 'rgb(212, 175, 55)',
                    pointBackgroundColor: 'rgb(212, 175, 55)',
                    pointBorderColor: '#fff',
                    pointHoverBackgroundColor: '#fff',
                    pointHoverBorderColor: 'rgb(212, 175, 55)'
                }]
            },
            options: {
                scales: {
                    r: {
                        angleLines: {
                            color: 'rgba(192, 169, 214, 0.5)'
                        },
                        grid: {
                            color: 'rgba(192, 169, 214, 0.3)'
                        },
                        pointLabels: {
                            color: '#d4af37',
                            font: {
                                size: 12,
                                weight: 'bold'
                            }
                        },
                        suggestedMin: 0,
                        suggestedMax: 18,
                        ticks: {
                            color: 'rgba(192, 169, 214, 0.7)',
                            backdropColor: 'transparent'
                        }
                    }
                },
                plugins: {
                    legend: {
                        display: false
                    }
                },
                elements: {
                    line: {
                        borderWidth: 2
                    }
                }
            }
        });

        // 计算属性调整值
        function calculateModifier(value) {
            if (value <= 1) return -5;
            if (value <= 3) return -4;
            if (value <= 5) return -3;
            if (value <= 7) return -2;
            if (value <= 9) return -1;
            if (value <= 11) return 0;
            if (value <= 13) return 1;
            if (value <= 15) return 2;
            if (value <= 17) return 3;
            if (value <= 19) return 4;
            if (value <= 21) return 5;
            if (value <= 23) return 6;
            if (value <= 25) return 7;
            if (value <= 27) return 8;
            if (value <= 29) return 9;
            return 10;
        }

        // 计算属性花费
        function calculateCost(value) {
            if (value <= 13) return value - baseStat;
            return 5 + (value - 13) * 2;
        }

        // 更新UI显示
        function updateUI() {
            let totalUsed = 0;

            // 更新所有属性显示
            for (const stat in stats) {
                document.getElementById(`${stat}-value`).textContent = stats[stat].value;
                document.getElementById(`${stat}-cost`).textContent = stats[stat].cost;

                // 更新调整值
                const modifier = calculateModifier(stats[stat].value);
                const modifierText = modifier >= 0 ? `+${modifier}` : modifier;
                document.getElementById(`${stat}-mod`).textContent = modifierText;

                totalUsed += stats[stat].cost;
            }

            // 更新点数摘要
            document.getElementById('used-points').textContent = totalUsed;
            document.getElementById('remaining-points').textContent = totalPoints - totalUsed;

            // 更新按钮状态
            updateButtonStates(totalUsed);

            // 更新雷达图
            updateRadarChart();

            // 更新确认面板
            updateConfirmationPanel();
        }

        // 更新雷达图数据
        function updateRadarChart() {
            radarChart.data.datasets[0].data = [
                stats.str.value, 
                stats.dex.value, 
                stats.con.value, 
                stats.int.value, 
                stats.wis.value, 
                stats.cha.value
            ];
            radarChart.update();
        }

        // 更新确认面板
        function updateConfirmationPanel() {
            const name = document.getElementById('char-name').value.trim() || '{{user}}';
            const age = document.getElementById('char-age').value || '未设置';
            const gender = document.getElementById('char-gender').value.trim() || '未设置';
            const appearance = document.getElementById('char-appearance').value.trim() || '未设置';

            let totalUsed = 0;
            for (const stat in stats) {
                totalUsed += stats[stat].cost;
            }

            // 更新基本信息
            document.getElementById('confirm-name').textContent = `姓名：${name}`;
            document.getElementById('confirm-age').textContent = `年龄：${age}`;
            document.getElementById('confirm-gender').textContent = `性别：${gender}`;
            document.getElementById('confirm-appearance').textContent = `外貌：${appearance || '无描述'}`;

            // 更新属性值
            document.getElementById('confirm-str').textContent = stats.str.value;
            document.getElementById('confirm-dex').textContent = stats.dex.value;
            document.getElementById('confirm-con').textContent = stats.con.value;
            document.getElementById('confirm-int').textContent = stats.int.value;
            document.getElementById('confirm-wis').textContent = stats.wis.value;
            document.getElementById('confirm-cha').textContent = stats.cha.value;

            // 更新点数使用
            document.getElementById('confirm-used').textContent = totalUsed;

            // 更新技能列表
            const skillsList = document.getElementById('skills-list');
            skillsList.innerHTML = '';

            if (selectedSkills.length === 0) {
                document.getElementById('confirm-skills').textContent = '无';
            } else {
                document.getElementById('confirm-skills').textContent = `已选${selectedSkills.length}个技能`;
                selectedSkills.forEach(skill => {
                    const skillEl = document.createElement('div');
                    skillEl.className = 'skill-confirm';
                    skillEl.textContent = skill;
                    skillsList.appendChild(skillEl);
                });
            }
        }

        // 更新按钮状态
        function updateButtonStates(totalUsed) {
            for (const stat in stats) {
                const decBtn = document.getElementById(`${stat}-dec`);
                const incBtn = document.getElementById(`${stat}-inc`);

                // 减少按钮：如果属性值大于8则可用
                decBtn.disabled = stats[stat].value <= baseStat;

                // 增加按钮：如果剩余点数不足或属性值达到上限则禁用
                incBtn.disabled = (totalUsed >= totalPoints) || stats[stat].value >= 16;
            }
        }

        // 属性调整函数
        function adjustStat(stat, delta) {
            const newValue = stats[stat].value + delta;

            // 检查边界
            if (newValue < baseStat || newValue > 16) return;

            // 计算新值的花费
            const newCost = calculateCost(newValue);

            // 检查是否有足够的点数
            const costDelta = newCost - stats[stat].cost;
            let totalUsed = 0;
            for (const s in stats) {
                totalUsed += stats[s].cost;
            }

            if (totalUsed + costDelta > totalPoints) return;

            // 更新值
            stats[stat].value = newValue;
            stats[stat].cost = newCost;

            // 更新UI
            updateUI();
            validate();
        }

        // 重置所有属性
        function resetStats() {
            for (const stat in stats) {
                stats[stat].value = baseStat;
                stats[stat].cost = 0;
            }

            updateUI();
            validate();
        }

        // 技能选择功能
        function toggleSkill(skillCard) {
            const skillName = skillCard.getAttribute('data-skill');

            if (selectedSkills.includes(skillName)) {
                // 取消选择
                skillCard.classList.remove('selected');
                selectedSkills = selectedSkills.filter(skill => skill !== skillName);
            } else {
                // 检查是否已达到最大选择数
                if (selectedSkills.length >= maxSkills) return;

                // 选择技能
                skillCard.classList.add('selected');
                selectedSkills.push(skillName);
            }

            // 更新已选择技能计数
            document.getElementById('selected-count').textContent = selectedSkills.length;

            // 锁定/解锁技能卡片
            const skillCards = document.querySelectorAll('.skill-card');
            skillCards.forEach(card => {
                const cardSkill = card.getAttribute('data-skill');
                if (!selectedSkills.includes(cardSkill) && selectedSkills.length >= maxSkills) {
                    card.classList.add('disabled');
                } else {
                    card.classList.remove('disabled');
                }
            });

            updateUI();
            validate();
        }

        // 验证表单是否完整
        function validate() {
            const name = document.getElementById('char-name').value.trim();
            const age = document.getElementById('char-age').value;
            const gender = document.getElementById('char-gender').value.trim();
            const appearance = document.getElementById('char-appearance').value.trim();

            let totalUsed = 0;
            for (const stat in stats) {
                totalUsed += stats[stat].cost;
            }

            let message = '';

            if (!name && !age && !gender && !appearance) {
                message = '请填写个人信息';
            } else if (totalUsed < totalPoints) {
                message = '请分配所有属性点';
            } else if (selectedSkills.length < maxSkills) {
                message = `请选择${maxSkills}个技能`;
            }

            document.getElementById('validation-message').textContent = message;
            document.getElementById('validation-message').style.opacity = message ? 1 : 0;
            document.getElementById('submit-btn').disabled = !!message;

            return !message;
        }

        // 显示感谢页面
        function showCredits() {
            const creditsScreen = document.getElementById('credits-screen');
            creditsScreen.style.opacity = 1;
            creditsScreen.style.pointerEvents = 'all';
        }

        // 提交表单
        async function submitForm() {
            if (!validate()) return;

            const submitBtn = document.getElementById('submit-btn');
            submitBtn.disabled = true;

            // 获取角色数据
            const name = document.getElementById('char-name').value.trim() || '{{user}}';
            const age = document.getElementById('char-age').value || '未设置';
            const gender = document.getElementById('char-gender').value.trim() || '未设置';
            const appearance = document.getElementById('char-appearance').value.trim() || '无';

            const attrs = {
                strength: stats.str.value,
                dexterity: stats.dex.value,
                constitution: stats.con.value,
                intelligence: stats.int.value,
                wisdom: stats.wis.value,
                charisma: stats.cha.value
            };

            // 构造发送给SillyTavern的数据
            const finalCharacterObject = {
                NAME: name,
                GENDER: gender,
                AGE: age.toString(),
                APPEARANCE: appearance,
                ATTRS: {
                    力量: attrs.strength,
                    敏捷: attrs.dexterity,
                    体质: attrs.constitution,
                    智力: attrs.intelligence,
                    感知: attrs.wisdom,
                    魅力: attrs.charisma
                },
                PROFICIENCIES: selectedSkills,
                PROFICIENCY_DESC: selectedSkills.join('，') || '无'
            };

            const slashCommand = `/send <START>
随着你轻点按钮，系统发出清脆的响声，你的角色表已打包并发送给了艾舍丝。

屏幕上显示出了你的详细信息：
# 异世界角色档案
---
## 基础信息
- **姓名:** ${finalCharacterObject.NAME}
- **性别:** ${finalCharacterObject.GENDER}
- **年龄:** ${finalCharacterObject.AGE}
- **外形描述:** ${finalCharacterObject.APPEARANCE}

## 属性
- **力量:** ${attrs.strength}
- **敏捷:** ${attrs.dexterity}
- **体质:** ${attrs.constitution}
- **智力:** ${attrs.intelligence}
- **感知:** ${attrs.wisdom}
- **魅力:** ${attrs.charisma}

## 熟练项
- **已选熟练项:** ${finalCharacterObject.PROFICIENCY_DESC}
|
/trigger`;

            // 在实际环境中，这里会调用SillyTavern的API
            try {
                if (typeof insertOrAssignVariables === 'function') { 
                    await insertOrAssignVariables(finalCharacterObject);
                } else {
                    console.log("SillyTavern Function 'insertOrAssignVariables' not found. Variables:", finalCharacterObject);
                }

                if (typeof triggerSlash === 'function') { 
                    await triggerSlash(slashCommand, 'Send');
                } else {
                    console.log("SillyTavern Function 'triggerSlash' not found. Command will be copied to clipboard.");
                    navigator.clipboard.writeText(slashCommand).then(() => {
                        alert('角色指令已复制到剪贴板！');
                    });
                }
            } catch (error) {
                console.error('与SillyTavern交互失败:', error);
                alert('与SillyTavern交互失败，请查看浏览器控制台。');
            }

            // 显示感谢页面
            showCredits();
        }

        // 事件监听器设置
        function setupEventListeners() {
            // 属性按钮事件
            for (const stat in stats) {
                document.getElementById(`${stat}-inc`).addEventListener('click', () => adjustStat(stat, 1));
                document.getElementById(`${stat}-dec`).addEventListener('click', () => adjustStat(stat, -1));
            }

            // 重置按钮事件
            document.getElementById('reset-btn').addEventListener('click', resetStats);

            // 技能选择事件
            const skillCards = document.querySelectorAll('.skill-card');
            skillCards.forEach(card => {
                card.addEventListener('click', () => toggleSkill(card));
            });

            // 提交按钮事件
            document.getElementById('submit-btn').addEventListener('click', submitForm);

            // 个人信息输入事件
            ['char-name', 'char-age', 'char-gender', 'char-appearance'].forEach(id => {
                document.getElementById(id).addEventListener('input', () => {
                    updateUI();
                    validate();
                });
            });
        }

        // 初始化
        document.addEventListener('DOMContentLoaded', () => {
            updateUI();
            setupEventListeners();
            validate();
        });
    </script>
</body>
</html>
