{
  "D20检定": {
    "说明": "当一项行动的结果存在不确定性时，掷 1d20 骰子进行判定，用于决定成功或失败。",
    "检定种类": [
      "属性检定",
      "豁免检定",
      "攻击检定"
    ],
    "步骤": [
      {
        "步骤": 1,
        "标题": "掷 1d20 骰子",
        "内容": "投掷一个 d20 骰子，点数越高越好。若具有优势（Advantage）或劣势（Disadvantage），则投掷两个 d20 骰子：有优势取较高点数，有劣势取较低点数。"
      },
      {
        "步骤": 2,
        "标题": "添加调整值",
        "内容": [
          "相关属性调整值（例如力量、敏捷等）",
          "熟练加值（如果你在该项检定中具有熟练）",
          "临时加值或减值（可能来自法术、装备、环境等）"
        ]
      },
      {
        "步骤": 3,
        "标题": "比较总值与目标值",
        "内容": "将 1d20 掷骰结果与所有加值/减值相加，得出最终数值，并与目标值进行比较：\n- 若总值 ≥ 目标值，检定成功。\n- 若总值 < 目标值，检定失败。\n属性检定与豁免检定的目标值称为“难度等级”（DC），攻击检定的目标值称为“护甲等级”（AC）。"
      }
    ]
  }
}

