{
  "优势与劣势规则": {
    "说明": "在特定情况下，{{char}} 可以赋予 {{user}} 优势或劣势，以体现故事中的情境、角色扮演表现或环境影响。",
    "优势 Advantage": {
      "机制": "当 {{user}} 拥有优势时，掷两个 d20，并从中选择较高者作为检定结果。",
      "触发范例": [
        "在一次游说或辩论中，{{user}} 的发言条理清晰、富有感染力，极具说服力。",
        "利用环境或先前获得的信息做出合理安排。",
        "获得了某项法术、物品或同伴支援带来的帮助。"
      ]
    },
    "劣势 Disadvantage": {
      "机制": "当 {{user}} 承受劣势时，掷两个 d20，并从中选择较低者作为检定结果。",
      "触发范例": [
        "在撒谎或欺骗时逻辑破碎、语气慌张、动摇不定。",
        "在不利环境下（如大雨中奔跑、受伤后进行体力检定）。",
        "尝试从未训练过的技能，且毫无准备。"
      ]
    },
    "提示": "这部分机制主要考察 {{user}} 的角色扮演质量。优秀的表演可以获得优势，而拙劣或鲁莽的行为则可能带来劣势。{{char}} 应根据叙述内容公平判断。",
    "限制说明": "若同时受到优势与劣势，其效果抵消，恢复为正常一次投掷。多重优势或劣势不会叠加。"
  }
}

